Evaluate the JavaScript flight simulator implementation on a scale of 0-10 points:

**3D Flight Simulation (4 points)**: Does it render a convincing 3D flight view with horizon, terrain, and responsive aircraft controls? Is the flight physics realistic?

**Intentional Bug Implementation (3 points)**: Does it include the specified realistic aviation bugs (instrument lag, altimeter stickiness, compass deviation, engine fluctuation) that are clearly documented as intentional features?

**HUD and Interface (2 points)**: Does it display accurate flight data (speed, altitude, heading, fuel) with visual indicators when bugs affect instruments?

**Performance and Code Quality (1 point)**: Does it run smoothly at 60 FPS with well-structured, documented code?

Solution A: function flightSimulator(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) throw new Error('Canvas not found');
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    // ---- Flight state ----
    const state = {
        // Position in meters (x forward, y right, z up)
        pos: { x: 0, y: 0, z: 1000 },
        // Velocity components in m/s
        vel: { x: 200, y: 0, z: 0 },
        // Orientation in radians
        pitch: 0, // nose up/down
        roll: 0, // bank left/right
        yaw: 0, // heading
        // Controls
        throttle: 0.7, // 0..1
        // Instruments (with intentional bugs)
        instrument: {
            speed: 0,
            altitude: 0,
            heading: 0,
            fuel: 100, // %
            // Bug helpers
            speedLagFrames: 0,
            altLagFrames: 0,
            headingLagFrames: 0,
            fuelLagFrames: 0,
            // For visual bug indication
            bugFlags: { speed: false, altitude: false, heading: false, engine: false }
        },
        // Fuel consumption rate (kg per second)
        fuelRate: 0.02,
        // Time accumulator for physics integration
        lastTime: null
    };

    // ---- Constants ----
    const G = 9.81; // m/s^2
    const MAX_THRUST = 20000; // Newtons (approx)
    const DRAG_COEFF = 0.0005;
    const MASS = 20000; // kg
    const MAX_SPEED = 340; // m/s ~ Mach 1
    const MIN_SPEED = 30; // stall speed approx.

    // ---- Input handling ----
    const keys = {};
    window.addEventListener('keydown', e => keys[e.code] = true);
    window.addEventListener('keyup', e => keys[e.code] = false);

    // ---- Helper functions ----
    function toDeg(rad) { return rad * 180 / Math.PI; }
    function toRad(deg) { return deg * Math.PI / 180; }
    function clamp(v, min, max) { return v < min ? min : v > max ? max : v; }

    // ---- Main loop ----
    function loop(timestamp) {
        if (!state.lastTime) state.lastTime = timestamp;
        const dt = (timestamp - state.lastTime) / 1000; // seconds
        state.lastTime = timestamp;

        updateControls(dt);
        integratePhysics(dt);
        updateInstruments(dt);
        render();

        requestAnimationFrame(loop);
    }

    // ---- Controls (throttle, pitch, roll, yaw) with simple keyboard mapping ----
    function updateControls(dt) {
        // Throttle: W increase, S decrease
        if (keys['KeyW']) state.throttle = clamp(state.throttle + 0.3 * dt, 0, 1);
        if (keys['KeyS']) state.throttle = clamp(state.throttle - 0.3 * dt, 0, 1);

        // Pitch: ArrowUp nose down, ArrowDown nose up (aircraft pitch positive = nose up)
        if (keys['ArrowUp']) state.pitch = clamp(state.pitch - 0.5 * dt, -toRad(30), toRad(30));
        if (keys['ArrowDown']) state.pitch = clamp(state.pitch + 0.5 * dt, -toRad(30), toRad(30));

        // Roll: ArrowLeft roll left, ArrowRight roll right
        if (keys['ArrowLeft']) state.roll = clamp(state.roll - 0.7 * dt, -toRad(60), toRad(60));
        if (keys['ArrowRight']) state.roll = clamp(state.roll + 0.7 * dt, -toRad(60), toRad(60));

        // Yaw (rudder): A yaw left, D yaw right
        if (keys['KeyA']) state.yaw -= 0.4 * dt;
        if (keys['KeyD']) state.yaw += 0.4 * dt;
        // Normalize yaw
        state.yaw = (state.yaw + Math.PI * 2) % (Math.PI * 2);
    }

    // ---- Physics integration (very simplified) ----
    function integratePhysics(dt) {
        // Engine thrust (intentionally reduced during steep climbs as a bug)
        let thrust = state.throttle * MAX_THRUST;
        if (Math.abs(state.pitch) > toRad(15)) {
            // Engine power fluctuation bug: random drop 10-30%
            const fluct = 0.7 + 0.3 * Math.random();
            thrust *= fluct;
            state.instrument.bugFlags.engine = true;
        } else {
            state.instrument.bugFlags.engine = false;
        }

        // Compute acceleration forward direction
        const forwardX = Math.cos(state.pitch) * Math.cos(state.yaw);
        const forwardY = Math.cos(state.pitch) * Math.sin(state.yaw);
        const forwardZ = Math.sin(state.pitch);

        const accel = {
            x: (thrust / MASS) * forwardX - DRAG_COEFF * state.vel.x,
            y: (thrust / MASS) * forwardY - DRAG_COEFF * state.vel.y,
            z: (thrust / MASS) * forwardZ - DRAG_COEFF * state.vel.z - G
        };

        // Simple Euler integration
        state.vel.x += accel.x * dt;
        state.vel.y += accel.y * dt;
        state.vel.z += accel.z * dt;

        // Clamp speed
        const speed = Math.sqrt(state.vel.x ** 2 + state.vel.y ** 2 + state.vel.z ** 2);
        if (speed > MAX_SPEED) {
            const scale = MAX_SPEED / speed;
            state.vel.x *= scale;
            state.vel.y *= scale;
            state.vel.z *= scale;
        }
        if (speed < MIN_SPEED) {
            const scale = MIN_SPEED / speed;
            state.vel.x *= scale;
            state.vel.y *= scale;
            state.vel.z *= scale;
        }

        // Update position
        state.pos.x += state.vel.x * dt;
        state.pos.y += state.vel.y * dt;
        state.pos.z += state.vel.z * dt;

        // Prevent underground
        if (state.pos.z < 0) {
            state.pos.z = 0;
            state.vel.z = 0;
        }

        // Fuel consumption (simple linear with throttle)
        state.instrument.fuel = clamp(state.instrument.fuel - state.fuelRate * state.throttle * dt * 100, 0, 100);
    }

    // ---- Instrument updates with intentional bugs ----
    function updateInstruments(dt) {
        // Compute true values
        const trueSpeed = Math.sqrt(state.vel.x ** 2 + state.vel.y ** 2 + state.vel.z ** 2);
        const trueAltitude = state.pos.z;
        let trueHeading = toDeg(state.yaw);
        if (trueHeading < 0) trueHeading += 360;

        // ---- Speed lag under high G (bug) ----
        const gForce = Math.sqrt(state.vel.x ** 2 + state.vel.y ** 2 + (state.vel.z + G) ** 2) / G;
        if (gForce > 2.5) {
            // Instrument lags: freeze speed reading for 1 second
            state.instrument.speedLagFrames = Math.max(state.instrument.speedLagFrames, Math.round(60));
            state.instrument.bugFlags.speed = true;
        }
        if (state.instrument.speedLagFrames > 0) {
            state.instrument.speedLagFrames--;
        } else {
            state.instrument.speed = trueSpeed;
            state.instrument.bugFlags.speed = false;
        }

        // ---- Altimeter stickiness at certain altitude bands (bug) ----
        const band = 1000; // meters
        const lower = Math.floor(trueAltitude / band) * band;
        const upper = lower + band;
        if (Math.abs(trueAltitude - lower) < 20 || Math.abs(trueAltitude - upper) < 20) {
            // Stickiness: hold previous reading for 0.5 sec
            state.instrument.altLagFrames = Math.max(state.instrument.altLagFrames, Math.round(30));
            state.instrument.bugFlags.altitude = true;
        }
        if (state.instrument.altLagFrames > 0) {
            state.instrument.altLagFrames--;
        } else {
            state.instrument.altitude = trueAltitude;
            state.instrument.bugFlags.altitude = false;
        }

        // ---- Compass deviation near magnetic anomalies (bug) ----
        // Define anomaly zones (e.g., around 90° and 270°)
        const anomalies = [{center: 90, range: 15}, {center: 270, range: 15}];
        let deviation = 0;
        for (const a of anomalies) {
            const diff = Math.abs(((trueHeading - a.center + 180 + 360) % 360) - 180);
            if (diff < a.range) {
                // Apply deviation up to ±5°
                deviation = (Math.random() - 0.5) * 10;
                state.instrument.headingLagFrames = Math.max(state.instrument.headingLagFrames, Math.round(30));
                state.instrument.bugFlags.heading = true;
                break;
            }
        }
        if (state.instrument.headingLagFrames > 0) {
            state.instrument.headingLagFrames--;
            // keep previous heading display
        } else {
            state.instrument.heading = (trueHeading + deviation + 360) % 360;
            state.instrument.bugFlags.heading = false;
        }

        // Fuel gauge is immediate (no bug)
        state.instrument.fuel = state.instrument.fuel;
    }

    // ---- Rendering ----
    function render() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        drawSkyAndHorizon();
        drawTerrain();
        drawHUD();
    }

    function drawSkyAndHorizon() {
        // Simple gradient sky
        const grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
        grad.addColorStop(0, '#87CEEB');
        grad.addColorStop(0.5, '#87CEEB');
        grad.addColorStop(1, '#3A5F0B');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    function drawTerrain() {
        // Very simple pseudo‑3D terrain strips based on forward position
        const stripCount = 30;
        const spacing = 100; // meters
        const camHeight = state.pos.z;
        const camPitch = state.pitch;
        for (let i = 1; i <= stripCount; i++) {
            const depth = i * spacing;
            const worldZ = state.pos.z - depth * Math.sin(camPitch);
            const worldY = state.pos.y;
            const scale = 300 / (depth * Math.cos(camPitch) + 1);
            const lineY = canvas.height / 2 + (camHeight - worldZ) * scale;
            const lineWidth = canvas.width * scale;
            ctx.strokeStyle = '#654321';
            ctx.lineWidth = Math.max(1, scale * 5);
            ctx.beginPath();
            ctx.moveTo((canvas.width - lineWidth) / 2, lineY);
            ctx.lineTo((canvas.width + lineWidth) / 2, lineY);
            ctx.stroke();
        }
    }

    function drawHUD() {
        ctx.fillStyle = '#FFFFFF';
        ctx.font = '14px monospace';
        const padding = 10;

        // Speed
        drawInstrumentBox('SPD', (state.instrument.speed).toFixed(0) + ' m/s', padding, padding, state.instrument.bugFlags.speed);

        // Altitude
        drawInstrumentBox('ALT', (state.instrument.altitude).toFixed(0) + ' m', padding, 30 + padding, state.instrument.bugFlags.altitude);

        // Heading
        drawInstrumentBox('HDG', (state.instrument.heading).toFixed(0) + '°', padding, 60 + padding, state.instrument.bugFlags.heading);

        // Fuel
        drawInstrumentBox('FUEL', state.instrument.fuel.toFixed(1) + '%', padding, 90 + padding, false);

        // Throttle indicator (bottom right)
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'right';
        ctx.fillText('THR: ' + Math.round(state.throttle * 100) + '%', canvas.width - padding, canvas.height - padding);
        ctx.textAlign = 'left';
    }

    function drawInstrumentBox(label, value, x, y, bugActive) {
        const boxWidth = 120;
        const boxHeight = 20;
        ctx.strokeStyle = bugActive ? '#FF0000' : '#FFFFFF';
        ctx.lineWidth = bugActive ? 2 : 1;
        ctx.strokeRect(x, y, boxWidth, boxHeight);
        ctx.fillStyle = '#FFFFFF';
        ctx.fillText(label + ': ' + value, x + 5, y + 15);
    }

    // Start animation loop
    requestAnimationFrame(loop);
}

Solution B: ```javascript
function flightSimulator(canvasId) {
  const canvas = document.getElementById(canvasId);
  if (!canvas) return;
  canvas.width = 500;
  canvas.height = 500;
  const ctx = canvas.getContext('2d');

  // Aircraft state
  let state = {
    x: 250,
    y: 250,
    speed: 0,              // m/s
    altitude: 0,           // ft
    heading: 0,            // degrees 0-359
    throttle: 0,           // 0-100
    pitch: 0,              // -90 to +90
    roll: 0,               // -180 to +180
    fuel: 1000             // units
  };

  // Input flags
  const input = {
    throttleUp: false,
    throttleDown: false,
    pitchUp: false,
    pitchDown: false,
    rollLeft: false,
    rollRight: false,
    yawLeft: false,
    yawRight: false
  };

  // Bug related buffers
  const instrumentBuffers = {
    speed: [], // [value, time]
    altitude: [],
    heading: [],
  };
  const bufferDelay = 0.5 * 1000; // 0.5 seconds delay in ms

  // Altimeter stickiness zone
  const stickinessZone = { min: 8500, max: 8600 }; // ft
  let altStickTimer = 0;
  const altStickDuration = 3000; // 3 seconds
  let altDisplayed = state.altitude;

  // Compass anomaly zone
  const anomalyHeading = 90; // degrees
  const anomalyRange = 10; // degrees
  let compassDeviated = false;
  let compassDisplay = state.heading;

  // Engine fluctuation during steep climbs
  let engineFluctuate = false;
  let throttleDisplay = state.throttle;

  // Helper functions
  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function wrapAngle(angle) {
    return ((angle % 360) + 360) % 360;
  }

  // Input handling
  window.addEventListener('keydown', (e) => {
    switch (e.code) {
      case 'ArrowUp': input.throttleUp = true; break;
      case 'ArrowDown': input.throttleDown = true; break;
      case 'KeyW': input.pitchUp = true; break;
      case 'KeyS': input.pitchDown = true; break;
      case 'KeyA': input.rollLeft = true; break;
      case 'KeyD': input.rollRight = true; break;
      case 'KeyQ': input.yawLeft = true; break;
      case 'KeyE': input.yawRight = true; break;
    }
  });
  window.addEventListener('keyup', (e) => {
    switch (e.code) {
      case 'ArrowUp': input.throttleUp = false; break;
      case 'ArrowDown': input.throttleDown = false; break;
      case 'KeyW': input.pitchUp = false; break;
      case 'KeyS': input.pitchDown = false; break;
      case 'KeyA': input.rollLeft = false; break;
      case 'KeyD': input.rollRight = false; break;
      case 'KeyQ': input.yawLeft = false; break;
      case 'KeyE': input.yawRight = false; break;
    }
  });

  // Main loop
  let lastTime = performance.now();
  function tick(now) {
    const dt = (now - lastTime) / 1000; // seconds
    lastTime = now;

    // Update controls
    if (input.throttleUp) state.throttle = clamp(state.throttle + 20 * dt, 0, 100);
    if (input.throttleDown) state.throttle = clamp(state.throttle - 20 * dt, 0, 100);
    if (input.pitchUp) state.pitch = clamp(state.pitch + 30 * dt, -90, 90);
    if (input.pitchDown) state.pitch = clamp(state.pitch - 30 * dt, -90, 90);
    if (input.rollLeft) state.roll = clamp(state.roll - 60 * dt, -180, 180);
    if (input.rollRight) state.roll = clamp(state.roll + 60 * dt, -180, 180);
    if (input.yawLeft) state.heading = wrapAngle(state.heading - 45 * dt);
    if (input.yawRight) state.heading = wrapAngle(state.heading + 45 * dt);

    // Simplified physics
    const thrust = state.throttle * 1; // arbitrary units
    const pitchAccel = Math.sin(state.pitch * Math.PI / 180) * 9.81;
    const rollAccel = Math.sin(state.roll * Math.PI / 180) * 9.81;
    const totalG = Math.sqrt(pitchAccel * pitchAccel + rollAccel * rollAccel) / 9.81;

    // Speed update
    state.speed = clamp(state.speed + (thrust - 5) * dt, 0, 300);
    // Altitude update
    state.altitude = clamp(state.altitude + pitchAccel * dt * 3, 0, 40000);

    // Fuel consumption
    state.fuel = clamp(state.fuel - (state.throttle / 500) * dt, 0, 1000);
    if (state.fuel <= 0) state.fuel = 0;

    // Intentional bugs implementation
    const nowMs = now;

    // Instrument lag during high G forces
    if (totalG > 2) {
      instrumentBuffers.speed.push([state.speed, nowMs + bufferDelay]);
      instrumentBuffers.altitude.push([state.altitude, nowMs + bufferDelay]);
      instrumentBuffers.heading.push([state.heading, nowMs + bufferDelay]);
    } else {
      instrumentBuffers.speed.push([state.speed, nowMs]);
      instrumentBuffers.altitude.push([state.altitude, nowMs]);
      instrumentBuffers.heading.push([state.heading, nowMs]);
    }

    // Visual indicator for lag
    const lagActive = instrumentBuffers.speed[0][1] > nowMs;

    // Altimeter stickiness
    if (state.altitude >= stickinessZone.min && state.altitude <= stickinessZone.max) {
      if (!altStickTimer) altStickTimer = nowMs;
      if (nowMs - altStickTimer < altStickDuration) {
        state.altitude = altDisplayed; // freeze
      } else {
        altStickTimer = 0;
        altDisplayed = state.altitude;
      }
    } else {
      altStickTimer = 0;
      altDisplayed = state.altitude;
    }

    // Compass deviation near magnetic anomaly
    const headingDiff = Math.abs(state.heading - anomalyHeading);
    if (headingDiff < anomalyRange) {
      compassDeviated = true;
      compassDisplay = wrapAngle(state.heading + (anomalyRange - headingDiff));
    } else {
      compassDeviated = false;
      compassDisplay = state.heading;
    }

    // Engine power fluctuation during steep climbs
    if (state.pitch > 30) {
      engineFluctuate = true;
      throttleDisplay = clamp(state.throttle + (Math.random() - 0.5) * 20, 0, 100);
    } else {
      engineFluctuate = false;
      throttleDisplay = state.throttle;
    }

    // Rendering
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Terrain (simple)
    const terrainColor = state.altitude < 1000 ? '#556b2f' : '#a9a9a9';
    ctx.fillStyle = terrainColor;
    ctx.fillRect(0, 250, 500, 250);

    // Horizon line
    const horizonY = 250 + Math.sin(state.pitch * Math.PI / 180) * 50;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, horizonY);
    ctx.lineTo(500, horizonY);
    ctx.stroke();

    // Aircraft representation
    ctx.save();
    ctx.translate(state.x, state.y);
    ctx.rotate(-state.roll * Math.PI / 180);
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(-10, -5, 20, 10);
    ctx.restore();

    // HUD
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(10, 10, 300, 120);
    ctx.fillStyle = '#ffffff';
    ctx.font = '12px monospace';
    ctx.fillText(`Speed: ${(state.speed * 3.6).toFixed(1)} km/h`, 20, 35);
    ctx.fillText(`Altitude: ${altDisplayed.toFixed(0)} ft`, 20, 55);
    ctx.fillText(`Heading: ${Math.round(compassDisplay)}°`, 20, 75);
    ctx.fillText(`Throttle: ${throttleDisplay.toFixed(1)}%`, 20, 95);
    ctx.fillText(`Fuel: ${state.fuel.toFixed(0)}`, 20, 115);

    // Bug visual indicators
    if (lagActive) {
      ctx.strokeStyle = '#ff0000';
      ctx.lineWidth = 1;
      ctx.setLineDash([5, 3]);
      ctx.strokeRect(350, 50, 140, 90);
      ctx.setLineDash([]);
      ctx.fillStyle = '#ff0000';
      ctx.fillText('LAG', 410, 80);
    }
    if (compassDeviated) {
      ctx.strokeStyle = '#ff0000';
      ctx.lineWidth = 1;
      ctx.setLineDash([5, 3]);
      ctx.strokeRect(350, 160, 140, 90);
      ctx.setLineDash([]);
      ctx.fillStyle = '#ff0000';
      ctx.fillText('COMPS', 410, 190);
    }
    if (engineFluctuate) {
      ctx.strokeStyle = '#ff0000';
      ctx.lineWidth = 1;
      ctx.setLineDash([5, 3]);
      ctx.strokeRect(350, 270, 140, 90);
      ctx.setLineDash([]);
      ctx.fillStyle = '#ff0000';
      ctx.fillText('ENG', 410, 300);
    }
    if (altStickTimer) {
      ctx.strokeStyle = '#ff0000';
      ctx.lineWidth = 1;
      ctx.setLineDash([5, 3]);
      ctx.strokeRect(350, 380, 140, 90);
      ctx.setLineDash([]);
      ctx.fillStyle = '#ff0000';
      ctx.fillText('ALT', 410, 410);
    }

    // Update buffers: adopt values when delay passed
    for (const key of ['speed', 'altitude', 'heading']) {
      while (instrumentBuffers[key].length && instrumentBuffers[key][0][1] <= nowMs) {
        const val = instrumentBuffers[key].shift()[0];
        if (key === 'speed') state.speed = val;
        if (key === 'altitude') state.altitude = val;
        if (key === 'heading') state.heading = val;
      }
    }

    requestAnimationFrame(tick);
  }

  requestAnimationFrame(tick);
}
